async processBatch(batchId: string) {
  const jobs = await this.queue.addBulk(documents.map(d => ({
    name: 'pefin-include',
    data: { batchId, document: d },
  })));
  return { enqueued: jobs.length };
}

def normalizar_cpf_cnpj(valor):
    digitos = re.sub(r"\D", "", str(valor).strip())
